<script setup lang="tsx">
import { ref, computed, watch, onMounted, onBeforeUnmount } from "vue";
import { useRoute } from "vue-router";
import router from "@/router";
import { GetProblemJudge, PostJudgeDataAi, GetJudgeDataAi, GetJudgeDataAiList, GetAiPreviewZip, PostJudgeDataAiApply, PostJudgeDataAiCancel, PostJudgeDataAiRetry } from "@/apis/problem.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import { useWebStyleStore } from "@/stores/webStyle.ts";
import { AiTestdataJobView, AiTestdataStageView, AiTestdataLlmCallView } from "@/types/problem.ts";
import { GetFileSizeStr } from "@/util/file.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

let route = useRoute();
const { globalProperties } = useCurrentInstance();

const webStyleStore = useWebStyleStore();
const { isMobile } = useBreakpoint();

// ===== 题目信息（精简加载：仅取 id / 标题 / AI 开关 / 最近任务；权限由路由 auths 兜底） =====
const problemKey = ref("");
let problemId = 0;
const problemTitle = ref("");
const problemLoading = ref(false);
const aiEnabled = ref(false);

// ===== AI 生成测试数据 =====
const AI_STATUS_NAMES: Record<number, string> = {
  0: "等待开始",
  1: "排队中",
  2: "规划测试点",
  3: "撰写参考代码",
  4: "编译参考代码",
  5: "生成输入数据",
  6: "运行参考代码",
  7: "已完成",
  8: "生成失败",
  9: "已取消",
};

const aiHint = ref("");
const aiJobList = ref<AiTestdataJobView[]>([]);
const aiListLoading = ref(false);
const aiSelectedJobId = ref(0);
const aiJob = ref<AiTestdataJobView | null>(null);
const aiCreating = ref(false);
const aiApplying = ref(false);
const aiApplyDialogVisible = ref(false);
const aiKeep = ref<Record<string, boolean>>({});
const aiRetrySel = ref<Record<string, boolean>>({});
const aiDownloading = ref(false);
let aiTimer = -1 as any;
let aiFetchSeq = 0; // 拉取世代计数：放弃任务/卸载组件时自增，使在途请求的响应作废

// 提示词快捷预设：点击后填入文本框
const hintPresets = [
  { label: "覆盖边界", text: "覆盖 n=1 与 n=10^5 等边界情况，包含链状数据" },
  { label: "极端构造", text: "包含卡时间复杂度与卡常数的最坏情况构造数据" },
  { label: "大规模数据", text: "生成 12 个左右的测试点，包含大规模随机数据" },
];

const applyHintPreset = (text: string) => {
  aiHint.value = text;
};

const aiStatusName = computed(() => {
  if (!aiJob.value) return "";
  return AI_STATUS_NAMES[aiJob.value.status] ?? "未知";
});

const aiIsRunning = computed(() => {
  return aiJob.value !== null && aiJob.value.status <= 6;
});

const aiIsFinished = computed(() => {
  return aiJob.value !== null && aiJob.value.status === 7 && !aiJob.value.apply_time;
});

const aiProgressPercent = computed(() => {
  if (!aiJob.value || aiJob.value.task_total <= 0) return 0;
  return Math.min(99, Math.floor((aiJob.value.task_current / aiJob.value.task_total) * 100));
});

// 任务表格数据：把 result.tasks 映射为文件元数据列需要的字段（文件名/大小/输出限制）
const aiTasks = computed(() =>
  (aiJob.value?.result?.tasks ?? []).map((t) => ({
    ...t,
    score: t.score ?? 0,
    inFile: `${t.key}.in`,
    inFileSize: t.in_file_size ?? 0,
    outFile: `${t.key}.out`,
    outFileSize: t.out_file_size ?? 0,
    outLimit: t.out_limit ?? 0,
  }))
);

const aiSuccessCount = computed(() => aiTasks.value.filter((t) => t.status === "accepted").length);

const aiHasFailedTasks = computed(() => aiTasks.value.some((t) => t.status !== "accepted"));

// 预览数据是否已过期（R2 存储对象被清理）：过期后下载/应用/重试均需重新生成
const aiFileExpired = computed(() => aiJob.value?.file_expired === true);

// 重试作用域：勾选「重试」列的测试点（作用于所选数据）
const aiRetrySelectedKeys = computed(() =>
  aiTasks.value.filter((t) => aiRetrySel.value[t.key]).map((t) => t.key)
);

// 重试作用域：全部失败测试点（作用于全部数据）
const aiFailedKeys = computed(() =>
  aiTasks.value.filter((t) => t.status !== "accepted").map((t) => t.key)
);

// 阶段时间线数据：任务进行中时依赖 aiNow，每 100ms tick 重建（浅克隆阶段对象）。
// 仅靠外部 ref 变化无法可靠穿透 TDesign 组件层级：Vue 的 shouldUpdateComponent
// 对 props 做浅比较（st 对象引用不变则跳过子树），t-table 还可能按行对象缓存 cell；
// 实测只有数据身份变化（如轮询返回新对象）才会刷新，因此这里主动改变对象身份
const aiStages = computed(() => {
  const stages = aiJob.value?.stages ?? [];
  if (!aiIsRunning.value) return stages;
  void aiNow.value; // 依赖 aiNow：tick 时重建数组与阶段对象
  return stages.map((st) => ({ ...st }));
});

// 当前时间（running 阶段实时计算已用时长）
const aiNow = ref(Date.now());
let aiLastWall = Date.now();
let aiTickTimer = -1 as any;

// advanceAiNow 推进单调本地时钟：Date.now() 可能因系统校时（NTP/手动调整）回退，
// 导致耗时显示倒流；这里保证 aiNow 只增不减——正常每 100ms 前进，时钟回退时保持不动
const advanceAiNow = () => {
  aiLastWall = Math.max(aiLastWall, Date.now());
  aiNow.value = aiLastWall;
};

// 页面从后台恢复可见时立即刷新一次时间：浏览器会节流后台标签页的定时器，
// 不处理的话切回页面后耗时显示会有一段明显停滞
const handleAiVisibility = () => {
  if (document.visibilityState === "visible") {
    advanceAiNow();
  }
};

const stopAiTick = () => {
  if (aiTickTimer !== -1) {
    clearInterval(aiTickTimer);
    aiTickTimer = -1;
  }
  document.removeEventListener("visibilitychange", handleAiVisibility);
};

// running 时每 100ms tick，驱动「进行中」阶段耗时与 LLM 调用耗时按毫秒级刷新：
// 客户端以 insert_time/start_time 为锚点本地推算（无需等服务端轮询），
// 100ms 采样让 ms 单位的变化肉眼可见、更新节奏均匀；
// 之前 1s 采样叠加 3s 轮询重渲染，观感是忽快忽慢的跳动
watch(aiIsRunning, (running) => {
  if (running) {
    if (aiTickTimer === -1) {
      advanceAiNow();
      aiTickTimer = window.setInterval(() => {
        advanceAiNow();
      }, 100);
      document.addEventListener("visibilitychange", handleAiVisibility);
    }
  } else {
    stopAiTick();
  }
});

// 单调显示值缓存：键为展示项标识（llm:${id} / stage:${id}），值为该项已展示过的最大耗时。
// 客户端推算（本地时钟）与服务端落库值（服务端时钟）之间存在时钟偏差：
// running → success/fail 切换时若直接换用落库值，显示可能倒流。
// 不做精确时钟对齐，只以已展示最大值为下限，保证耗时只增不减
const aiDurationFloor = new Map<string, number>();

const monotonicDuration = (key: string, value: number) => {
  if (!Number.isFinite(value) || value < 0) value = 0;
  const floor = aiDurationFloor.get(key) ?? 0;
  const next = Math.max(floor, value);
  aiDurationFloor.set(key, next);
  return next;
};

// 行级锚点缓存：running 行/阶段的起始锚点（ms）。
// 锚点取 min(服务端起始时间, 首次渲染时本地时间)：
// 服务端起始时间早于本地时钟（常规情况）时直接按 insert_time/start_time 计算，
// 页面刷新/切回后仍显示真实已耗时，不会重新从 0 计时；
// 仅当服务端时钟超前本地时钟时退化为从首次渲染起跳，避免负差值长时间钳成 0ms 不跳动。
// 之后耗时 = aiNow - 锚点，由本地单调时钟驱动、永不回退
const aiAnchorMap = new Map<string, number>();

const liveRunningMs = (key: string, startMs: number) => {
  let anchor = aiAnchorMap.get(key);
  if (anchor === undefined) {
    anchor = Number.isFinite(startMs) ? Math.min(startMs, aiNow.value) : aiNow.value;
    aiAnchorMap.set(key, anchor);
  }
  return Math.max(0, aiNow.value - anchor);
};

// 切换/重置任务时清空单调缓存（row id 全局唯一，这里只是保险，避免跨任务串号）
watch(aiSelectedJobId, () => {
  aiDurationFloor.clear();
  aiAnchorMap.clear();
});

// 耗时格式化：<1s 用 ms，<60s 用 s，否则 min s
const formatDuration = (ms: number) => {
  if (!ms || ms <= 0) return "0ms";
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
  const min = Math.floor(ms / 60000);
  const sec = Math.round((ms % 60000) / 1000);
  return sec > 0 ? `${min}min ${sec}s` : `${min}min`;
};

// 阶段耗时：running 用锚点实时推算（客户端时钟偏差安全），否则用后端落库的 duration_ms；
// 经 monotonicDuration 保证切换时显示值不回退
const stageDuration = (st: AiTestdataStageView) => {
  const value =
    st.status === "running"
      ? liveRunningMs(`stage:${st.id}`, new Date(st.start_time).getTime())
      : st.duration_ms;
  return formatDuration(monotonicDuration(`stage:${st.id}`, value));
};

// 心跳新鲜度：后端每完成一个测试点（或写入阶段文案）都会刷新 modify_time，
// 前端据此区分「正在推进」与「判题机可能已失联」（aiNow 每 100ms tick 驱动刷新）
const lastUpdateAgo = computed(() => {
  if (!aiJob.value?.modify_time) return "";
  const ms = aiNow.value - new Date(aiJob.value.modify_time).getTime();
  if (ms < 0) return "刚刚";
  return formatDuration(ms) + " 前";
});

// 认领时间（本地时区 HH:mm:ss）
const claimTimeText = computed(() => {
  if (!aiJob.value?.judge_time) return "";
  const d = new Date(aiJob.value.judge_time);
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleTimeString("zh-CN", { hour12: false });
});

const aiDropKeys = computed(() =>
  aiTasks.value.filter((t) => !aiKeep.value[t.key]).map((t) => t.key)
);

// 应用按钮禁用：没有任何保留测试点时不允许应用
const aiApplyDisabled = computed(() => aiTasks.value.length - aiDropKeys.value.length <= 0);

// 任务状态对应的 tag 主题：进行中 primary / 完成 success / 失败 danger / 取消 default
const jobTagTheme = (status: number) => {
  if (status === 7) return "success";
  if (status === 8) return "danger";
  return status === 9 ? "default" : "primary";
};

const aiJobTagTheme = computed(() => (aiJob.value ? jobTagTheme(aiJob.value.status) : "primary"));

// 历史任务时间（本地时区 MM-DD HH:mm）
const formatJobTime = (t?: string) => {
  if (!t) return "";
  const d = new Date(t);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString("zh-CN", {
    hour12: false,
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
};

const clearAiTimer = () => {
  if (aiTimer !== -1) {
    clearTimeout(aiTimer);
    aiTimer = -1;
  }
};

// 拉取任务状态，运行中则 1 秒后继续轮询
// aiFetchSeq 为世代计数：放弃任务/卸载组件时自增，使在途请求的过期响应作废
const fetchAiJob = async () => {
  clearAiTimer();
  if (aiSelectedJobId.value <= 0) return;
  const seq = ++aiFetchSeq;
  let res: any;
  try {
    res = await GetJudgeDataAi(aiSelectedJobId.value);
  } catch (e) {
    // 网络瞬时错误不能中断轮询链：静默排下一次，否则界面会永久冻结在旧状态
    console.error(e);
    if (seq !== aiFetchSeq) return;
    aiTimer = setTimeout(fetchAiJob, 3000);
    return;
  }
  // 过期响应（任务已被放弃或组件已卸载）直接丢弃，防止复活轮询
  if (seq !== aiFetchSeq) return;
  if (res.code !== 0) {
    // 运行中任务的瞬时错误不应永久中断轮询：静默排下一次；非运行中才提示并停止
    if (aiJob.value && aiJob.value.status <= 6) {
      aiTimer = setTimeout(fetchAiJob, 3000);
      return;
    }
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  aiJob.value = res.data as AiTestdataJobView;
  // 同步刷新历史任务列表里当前任务的 status 标签（运行中也会变化）
  const listIdx = aiJobList.value.findIndex((j) => j.id === aiJob.value!.id);
  if (listIdx >= 0) {
    aiJobList.value[listIdx] = { ...aiJobList.value[listIdx], status: aiJob.value!.status };
  }
  // 初始化每个测试点的保留状态：accepted 默认保留，失败默认移除
  // 初始化重试勾选：失败的点默认勾选（重试所选测试点的常用场景）
  const keep: Record<string, boolean> = {};
  const retrySel: Record<string, boolean> = {};
  aiTasks.value.forEach((t) => {
    keep[t.key] = aiKeep.value[t.key] ?? t.status === "accepted";
    retrySel[t.key] = aiRetrySel.value[t.key] ?? t.status !== "accepted";
  });
  aiKeep.value = keep;
  aiRetrySel.value = retrySel;
  if (aiJob.value.status <= 6) {
    // 1 秒轮询：新 LLM 调用行「首次出现」的延迟从 3 秒降到约 1 秒
    aiTimer = setTimeout(fetchAiJob, 1000);
  }
};

// 拉取历史 AI 生成任务列表；有历史任务且尚未选中时默认选中最近一条
// seqAtStart 为发起时的世代快照：期间用户放弃/切换过任务，则返回后不再自动选中，防止复活已放弃的任务
const loadAiJobList = async (seqAtStart = aiFetchSeq) => {
  aiListLoading.value = true;
  try {
    const res = await GetJudgeDataAiList(problemId);
    if (res.code !== 0) return;
    aiJobList.value = (res.data as AiTestdataJobView[]) ?? [];
  } catch (e) {
    console.error(e);
    return;
  } finally {
    aiListLoading.value = false;
  }
  if (seqAtStart !== aiFetchSeq) return;
  if (aiJobList.value.length > 0 && aiSelectedJobId.value === 0) {
    aiSelectedJobId.value = aiJobList.value[0].id;
    await fetchAiJob();
  }
};

const handleSelectAiJob = (v: any) => {
  aiSelectedJobId.value = Number(v);
  // 切换任务后清空保留勾选与重试勾选，避免跨任务串号
  aiKeep.value = {};
  aiRetrySel.value = {};
  fetchAiJob();
};

// 下载 AI 预览测试数据 zip（后端返回预签名 URL）
const handleDownloadAiZip = async () => {
  if (aiFileExpired.value) {
    // 已标记过期：不再发起请求，直接提示用户重新生成
    ShowTextTipsError(globalProperties, "预览数据已过期，请重新生成");
    return;
  }
  aiDownloading.value = true;
  try {
    const res = await GetAiPreviewZip(aiSelectedJobId.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      // 100083：后端发现 R2 对象不存在并已标记过期，刷新任务状态让界面进入「已过期」展示
      if (res.code === 100083) {
        fetchAiJob();
      }
      return;
    }
    const url = res.data as string;
    if (url) {
      // 预签名 zip 为 application/zip：同窗口跳转触发下载，避免 async 回调里的 window.open 被 popup 拦截
      window.location.href = url;
    }
  } finally {
    aiDownloading.value = false;
  }
};

const handleStartAi = async () => {
  aiCreating.value = true;
  try {
    const res = await PostJudgeDataAi(problemId, aiHint.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    aiSelectedJobId.value = res.data.id;
    aiKeep.value = {};
    if (res.data.reused === true) {
      // 后端复用了该题已有的进行中任务，本次填写的提示词未生效
      ShowTextTipsError(globalProperties, "该题已有进行中的生成任务，已恢复其进度（本次填写的提示词未生效）");
    } else {
      ShowTextTipsSuccess(globalProperties, "生成任务已创建");
    }
    await fetchAiJob();
    // 刷新历史任务列表，让新任务出现在侧栏中
    loadAiJobList();
  } finally {
    aiCreating.value = false;
  }
};

const handleApplyAi = () => {
  aiApplyDialogVisible.value = true;
};

const handleConfirmApply = async () => {
  aiApplying.value = true;
  try {
    const res = await PostJudgeDataAiApply(aiSelectedJobId.value, aiDropKeys.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      // 100083：预览数据已过期，刷新任务状态让界面进入「已过期」展示
      if (res.code === 100083) {
        fetchAiJob();
      }
      return;
    }
    aiApplyDialogVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已应用为官方测试数据");
    aiJob.value = null;
    aiSelectedJobId.value = 0;
    // 刷新历史任务列表：自动选中最近一条（即刚应用的这条），展示「已应用」状态
    await loadAiJobList();
  } finally {
    aiApplying.value = false;
  }
};

// 放弃当前任务：通知后端取消（停止流水线与 LLM 开销、释放判题机槽位），
// 并清空展示回到发起区（不自动发起，供修改提示语后手动开始生成）
const handleResetAi = async () => {
  aiFetchSeq++; // 使在途请求作废，防止过期响应复活已放弃的任务
  clearAiTimer();
  if (aiSelectedJobId.value > 0) {
    try {
      await PostJudgeDataAiCancel(aiSelectedJobId.value);
    } catch (e) {
      // 取消失败不阻塞本地界面重置（任务可能已结束）
      console.error(e);
    }
  }
  aiJob.value = null;
  aiSelectedJobId.value = 0;
  aiKeep.value = {};
  aiRetrySel.value = {};
};

// 放弃并重新生成：先取消旧任务，再用当前提示语立即发起一次新的生成
const handleRestartAi = async () => {
  await handleResetAi();
  handleStartAi();
};

// 在当前任务上继续生成：不新开任务，把原任务重置回待认领，
// 判题机在原有时间线上追加新一轮生成（复用规划/标程/已通过测试点）。
// retryKeys 为本次要重新生成的测试点；为空表示重试全部失败的点
const handleRetryAi = async (retryKeys: string[] | null = null) => {
  if (aiSelectedJobId.value <= 0) return;
  aiCreating.value = true;
  try {
    const res = await PostJudgeDataAiRetry(aiSelectedJobId.value, retryKeys ?? []);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 续跑沿用同一任务 id，时间线向后扩展
    aiSelectedJobId.value = res.data.id;
    aiKeep.value = {};
    aiRetrySel.value = {};
    ShowTextTipsSuccess(globalProperties, "已在当前任务上继续生成，时间线将向后扩展（复用规划、参考代码与已通过测试点）");
    await fetchAiJob();
    loadAiJobList();
  } finally {
    aiCreating.value = false;
  }
};

// AI 任务表格的文件元数据列（与评测数据页的官方任务表格同构）
const aiFileColumns = [
  {
    title: "分数",
    colKey: "score",
    width: 70,
  },
  {
    title: "输入文件",
    colKey: "inFile",
  },
  {
    title: "输入文件大小",
    colKey: "inFileSize",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.inFileSize);
    },
  },
  {
    title: "输出文件",
    colKey: "outFile",
  },
  {
    title: "输出文件大小",
    colKey: "outFileSize",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.outFileSize);
    },
  },
  {
    title: "输出限制",
    colKey: "outLimit",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.outLimit);
    },
  },
];

const aiTaskTableColumns = computed(() => {
  const cols: any[] = [
    {
      title: "保留（应用）",
      colKey: "keep",
      width: 90,
      cell: (_: any, data: any) => {
        return (
          <t-checkbox
            modelValue={aiKeep.value[data.row.key]}
            onChange={(v: boolean) => (aiKeep.value[data.row.key] = v)}
          />
        );
      },
    },
    {
      title: "重试（重新生成）",
      colKey: "retrySel",
      width: 110,
      cell: (_: any, data: any) => {
        return (
          <t-checkbox
            modelValue={aiRetrySel.value[data.row.key]}
            onChange={(v: boolean) => (aiRetrySel.value[data.row.key] = v)}
          />
        );
      },
    },
    { title: "测试点", colKey: "key", width: 70 },
    { title: "用途", colKey: "purpose" },
    {
      title: "状态",
      colKey: "status",
      width: 110,
      cell: (_: any, data: any) => {
        const row = data.row;
        if (row.status === "accepted") {
          return <t-tag theme="success" variant="light">通过</t-tag>;
        }
        const reason = row.sandbox_status || row.fail_reason || "失败";
        return <t-tag theme="danger" variant="light">{reason}</t-tag>;
      },
    },
    ...aiFileColumns,
  ];
  if (isMobile.value) {
    return cols.filter(
      (c) => c.colKey !== "purpose" && c.colKey !== "inFileSize" && c.colKey !== "outFileSize"
    );
  }
  return cols;
});

// LLM 调用明细列
const llmCallColumns: any[] = [
  { title: "模型", colKey: "model", width: 140 },
  { title: "attempt", colKey: "attempt", width: 90 },
  {
    title: "耗时",
    colKey: "duration_ms",
    width: 100,
    cell: (_: any, data: any) => {
      const row = data.row;
      // running 行用锚点实时推算（客户端时钟偏差安全，aiNow 每 100ms tick 刷新），
      // 结束行用服务端落库值；经 monotonicDuration 保证切换时显示值不回退
      const value =
        row.status === "running" && row.insert_time
          ? liveRunningMs(`llm:${row.id}`, new Date(row.insert_time).getTime())
          : row.duration_ms;
      return formatDuration(monotonicDuration(`llm:${row.id}`, value));
    },
  },
  {
    title: "token",
    colKey: "tokens",
    cell: (_: any, data: any) => {
      const total = data.row.prompt_tokens + data.row.completion_tokens;
      return (
        <t-tooltip content={`输入 ${data.row.prompt_tokens} / 输出 ${data.row.completion_tokens}`}>
          <span>{total}</span>
        </t-tooltip>
      );
    },
  },
  {
    title: "状态",
    colKey: "status",
    width: 90,
    cell: (_: any, data: any) => {
      const s = data.row.status;
      const theme = s === "success" ? "success" : s === "fail" ? "danger" : "primary";
      return (
        <t-tag size="small" variant="light" theme={theme}>
          {s}
        </t-tag>
      );
    },
  },
  {
    title: "错误",
    colKey: "error",
    cell: (_: any, data: any) => <span style="color: #999">{data.row.error ?? ""}</span>,
  },
];

// t-table 的 cell 渲染函数不会随组件外部 ref（如 aiNow）自动重渲染：
// 数据数组引用不变时 Vue 会跳过子组件更新，running 行的耗时因此冻结。
// 这里在存在 running 行时克隆行对象（新身份强制 t-table 重渲染 cell），
// 配合 aiStages 的 tick 重建，让耗时随 100ms tick 实时跳动；
// 全部调用结束后复用原引用，避免无谓重渲染
const liveLlmCalls = (calls?: AiTestdataLlmCallView[]) => {
  void aiNow.value; // 依赖 aiNow：每次 tick 都会重新执行本函数
  if (!calls) return [];
  if (!calls.some((c) => c.status === "running")) return calls;
  return calls.map((c) => ({ ...c }));
};

onBeforeUnmount(() => {
  aiFetchSeq++; // 使在途请求作废，防止卸载后轮询泄漏
  clearAiTimer();
  stopAiTick();
});

// ===== 页面跳转 =====
const handleBack = () => {
  router.push({
    name: "manage-problem-judge",
    params: {
      problemKey: problemKey.value,
    },
  });
};

const handleClickView = () => {
  router.push({
    name: "problem-detail",
    params: {
      problemKey: problemKey.value,
    },
  });
};

// 精简加载题目：只取 id / 标题 / 权限 / AI 开关，以及最近一次任务 id（进行中继续轮询）
const loadProblem = async () => {
  const res = await GetProblemJudge(problemKey.value);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    await router.push({ name: "problem" });
    return;
  }

  const problem = res.data.problem;
  problemId = problem.id;
  problemTitle.value = problem.title;
  aiEnabled.value = res.data.ai_enabled === true;

  webStyleStore.setTitle(problem.title + " - AI 生成测试数据");

  const latestAiJobId = res.data.ai_job_id ?? 0;
  if (latestAiJobId > 0 && aiSelectedJobId.value === 0) {
    aiSelectedJobId.value = latestAiJobId;
    await fetchAiJob();
  }

  problemLoading.value = false;
};

onMounted(async () => {
  if (Array.isArray(route.params.problemKey)) {
    problemKey.value = route.params.problemKey[0];
  } else {
    problemKey.value = route.params.problemKey;
  }
  if (!problemKey.value) {
    ShowTextTipsError(globalProperties, "题目不存在");
    await router.push({ name: "problem" });
    return;
  }

  problemLoading.value = true;
  await loadProblem();
  // 拉取历史任务列表，供侧栏/移动端选择器展示与切换
  if (aiEnabled.value && problemId > 0) {
    await loadAiJobList();
  }
});
</script>

<template>
  <t-loading :loading="problemLoading">
    <div class="dida-ai-page">
