        <t-tag v-if="aiJob" size="small" :theme="aiJobTagTheme" variant="light">
          #{{ aiJob.id }} · {{ aiStatusName }}
        </t-tag>
      </div>

      <!-- 功能开关拦截（页面访问权限由路由 auths 与全局 View403 兜底） -->
      <t-card v-if="!problemLoading && !aiEnabled" class="dida-ai-card">
        <t-alert theme="warning" message="本题尚未开启 AI 生成测试数据功能。" />
