              <div v-if="!aiJob">
                <t-alert
                  theme="info"
                  message="AI 将阅读题面，规划测试点并撰写参考代码，在沙箱中运行产出标准输出。生成结果需人工确认后才会生效。"
                  style="margin-bottom: 12px"
                />
                <t-space direction="vertical" style="width: 100%">
                  <t-textarea
                    v-model="aiHint"
