                      {{ preset.label }}
                    </t-tag>
                  </div>
                  <t-button theme="primary" block @click="handleStartAi" :loading="aiCreating">
                    开始生成
                  </t-button>
                </t-space>
              </div>

              <!-- 进度区：任务进行中 -->
              <div v-else-if="aiIsRunning">
