                    <t-tag theme="primary" variant="light">{{ aiStatusName }}</t-tag>
                    <span class="dida-ai-stage-msg">{{ aiJob?.stage_message }}</span>
                  </div>
                  <!-- 队列与心跳信息：判断任务是否在推进、由谁处理 -->
                  <div class="dida-ai-meta">
                    <template v-if="aiJob?.judger">判题机 {{ aiJob.judger }}</template>
                    <template v-if="claimTimeText"> · 认领于 {{ claimTimeText }}</template>
                    <template v-if="lastUpdateAgo"> · 最后更新 {{ lastUpdateAgo }}</template>
