                      应用为官方测试数据（保留 {{ aiTasks.length - aiDropKeys.length }} / {{ aiTasks.length }} 个测试点）
                    </t-button>
                    <t-button
                      theme="default"
                      :disabled="aiFileExpired"
                      @click="handleDownloadAiZip"
                      :loading="aiDownloading"
                    >
                      {{ aiFileExpired ? "数据已过期" : "下载测试数据" }}
                    </t-button>
                    <!-- 重试作用域：所选测试点（仅重新生成勾选「重试」列的点） -->
                    <t-button
                      v-if="aiHasFailedTasks && !aiFileExpired"
