                      variant="outline"
                      :disabled="aiRetrySelectedKeys.length === 0"
                      @click="handleRetryAi(aiRetrySelectedKeys)"
                      :loading="aiCreating"
                    >
                      重试所选测试点（{{ aiRetrySelectedKeys.length }}）
                    </t-button>
                    <!-- 重试作用域：全部数据（重新生成所有失败的测试点） -->
                    <t-button
                      v-if="aiHasFailedTasks && !aiFileExpired"
